CREATE TABLE IF NOT EXISTS metric_snapshots(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),platform TEXT NOT NULL,campaign_id TEXT REFERENCES campaigns(id),content_id TEXT REFERENCES content_items(id),metric_name TEXT NOT NULL,value_json TEXT NOT NULL,period_start TEXT NOT NULL,period_end TEXT NOT NULL,provider TEXT NOT NULL,source_ref TEXT,retrieved_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS reports(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),period_start TEXT NOT NULL,period_end TEXT NOT NULL,measured_facts_json TEXT NOT NULL,interpretation_json TEXT NOT NULL,next_priorities_json TEXT NOT NULL,open_risks_json TEXT NOT NULL,generated_by TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS applications(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),company TEXT NOT NULL,role TEXT NOT NULL,job_url TEXT NOT NULL,source TEXT NOT NULL,date_found TEXT,date_applied TEXT,resume_version TEXT,cover_letter_version TEXT,portfolio_version TEXT,status TEXT NOT NULL,recruiter TEXT,follow_up_at TEXT,interview_at TEXT,notes TEXT,outcome TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS portfolio_items(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),title TEXT NOT NULL,origin_label TEXT NOT NULL,metric_status TEXT NOT NULL,description TEXT NOT NULL,evidence_refs_json TEXT NOT NULL DEFAULT '[]',created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sops(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),name TEXT NOT NULL,cadence TEXT NOT NULL,steps_json TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
